css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

body { display: flex; min-height: 100vh; }

/* ---- menu lateral ---- */
.bs-side {
  position: sticky; top: 0;
  display: flex; flex-direction: column; flex-shrink: 0;
  width: 240px; height: 100vh;
  border-right: 1px solid var(--border); background: var(--bg-surface);
}
.bs-side-topo {
  display: flex; align-items: center; gap: 10px;
  padding: 16px 12px 20px; border-bottom: 1px solid var(--border);
}
.bs-side-logo {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px;
  font-family: var(--fonte-titulo); font-size: 15px; font-weight: 700;
  color: var(--bg-base); background: var(--accent);
}
.bs-side-marca { font-family: var(--fonte-titulo); font-size: 14px; font-weight: 600; color: var(--text); }
.bs-side-nav { flex: 1; overflow-y: auto; padding: 12px; display: flex; flex-direction: column; gap: 16px; }
.bs-side-titulo {
  margin-bottom: 6px; padding: 0 10px;
  font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--text-muted);
}
.bs-side-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 10px; border: none; border-left: 2px solid transparent; border-radius: 8px;
  font-family: var(--fonte); font-size: 13px; font-weight: 500; text-align: left;
  color: var(--text-muted); background: transparent;
}
.bs-side-item:hover { color: var(--text); }
.bs-side-ativo { font-weight: 600; color: var(--text); background: var(--bg-card); border-left-color: var(--accent); }
.bs-side-icwrap { display: flex; flex-shrink: 0; }
.bs-side-ic { width: 16px; height: 16px; }
.bs-side-badge {
  margin-left: auto; padding: 1px 6px; border-radius: 999px;
  font-size: 10px; font-weight: 700; color: var(--bg-base); background: var(--accent);
}
.bs-side-user { display: flex; align-items: center; gap: 10px; padding: 12px; border-top: 1px solid var(--border); }
.bs-side-avatar {
  display: grid; place-items: center; flex-shrink: 0; width: 32px; height: 32px; border-radius: 8px;
  font-family: var(--fonte-titulo); font-size: 12px; font-weight: 700; color: var(--text); background: var(--bg-card);
}
.bs-side-userinfo { min-width: 0; }
.bs-side-username {
  font-size: 12px; font-weight: 600; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-side-userrole { font-size: 10px; color: var(--text-muted); }

/* ---- conteúdo ----
   min-width: 0 no flex item: sem isso, uma tabela ou um nome longo empurra a
   coluna e come o menu lateral. */
.bs-main { flex: 1; min-width: 0; padding: 32px; }
@media (max-width: 720px) { .bs-main { padding: 20px; } }

.bs-h1 { margin: 0 0 24px; font-family: var(--fonte-titulo); font-size: 24px; font-weight: 600; color: var(--text); }
.bs-link { font-size: 12px; font-weight: 600; color: var(--accent); text-decoration: none; }
.bs-link:hover { text-decoration: underline; }

/* auto-fit em todas as grades: o layout desce pra uma coluna sozinho. */
.bs-stats { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); margin-bottom: 24px; }
.bs-duo { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); margin-bottom: 24px; }

/* ---- stat card ---- */
.bs-stat { padding: 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-base); }
.bs-stat-topo { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.bs-stat-rotulo { font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); }
.bs-stat-ic { width: 14px; height: 14px; color: var(--text-muted); }
.bs-stat-valor {
  font-family: var(--fonte-titulo); font-size: 22px; font-weight: 600;
  letter-spacing: -0.02em; color: var(--text);
}
.bs-stat-delta { margin-top: 4px; font-size: 11px; font-weight: 600; }
.bs-pos { color: var(--success); }
.bs-neg { color: var(--danger); }
.bs-neu { color: var(--warning); }

/* ---- metas ---- */
.bs-meta { padding: 16px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface); }
.bs-meta-topo { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 12px; }
.bs-meta-titulo { font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600; color: var(--text); }
.bs-meta-titulo span { font-family: var(--fonte); font-size: 11px; font-weight: 400; color: var(--text-muted); }
.bs-meta-linha { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.bs-meta-valor {
  min-width: 0; font-family: var(--fonte-titulo); font-size: 19px; font-weight: 600;
  letter-spacing: -0.02em; color: var(--text);
}
.bs-meta-valor span { font-family: var(--fonte); font-size: 12px; font-weight: 500; color: var(--text-muted); }
@media (min-width: 768px) {
  .bs-meta-valor { font-size: 22px; }
  .bs-meta-valor span { font-size: 13px; }
}
.bs-meta-pct { flex-shrink: 0; font-size: 13px; font-weight: 600; color: var(--accent); }
.bs-barra { height: 8px; overflow: hidden; border-radius: 999px; background: var(--bg-card); }
.bs-barra-fill { height: 100%; border-radius: 999px; background: var(--accent); transition: width 0.3s ease; }
.bs-meta-ok { color: var(--success); }
.bs-meta-ok-bg { background: var(--success); }

/* ---- painéis ---- */
.bs-painel {
  display: flex; flex-direction: column; align-items: flex-start; gap: 12px;
  padding: 20px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}
.bs-painel-titulo { font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600; color: var(--text); }

.bs-tarefas { display: flex; flex-direction: column; gap: 8px; width: 100%; }
.bs-tarefa {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--bg-base);
}
.bs-check {
  width: 20px; height: 20px; flex-shrink: 0;
  border: 1px solid var(--border); border-radius: 6px; background: var(--bg-card);
}
.bs-tarefa-txt {
  flex: 1; min-width: 0; font-size: 13px; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-tarefa-pri {
  flex-shrink: 0; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-muted);
}

/* ---- cards de cadência ---- */
.bs-cads { display: flex; flex-direction: column; gap: 10px; width: 100%; }
.bs-cad { padding: 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-base); }
.bs-cad-atraso { border-color: #7f1d1d; }
.bs-cad-topo { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.bs-cad-av {
  display: grid; place-items: center; flex-shrink: 0; width: 36px; height: 36px; border-radius: 10px;
  font-family: var(--fonte-titulo); font-size: 13px; font-weight: 700;
  color: var(--bg-base); background: var(--cor);
}
.bs-cad-id { flex: 1; min-width: 0; }
.bs-cad-nome {
  font-size: 13px; font-weight: 600; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-cad-fonte { display: flex; align-items: center; gap: 6px; margin-top: 2px; font-size: 11px; color: var(--text-muted); }
.bs-cad-fonte span { width: 6px; height: 6px; flex-shrink: 0; border-radius: 999px; background: var(--cor); }
.bs-cad-badge {
  flex-shrink: 0; padding: 2px 8px; border-radius: 6px;
  font-family: var(--fonte-mono); font-size: 10px; font-weight: 700; font-variant-numeric: tabular-nums;
  color: var(--cor-b); background: color-mix(in srgb, var(--cor-b) 15%, transparent);
}
.bs-b-erro { --cor-b: var(--danger); }
.bs-b-esp { --cor-b: var(--warning); }
.bs-cad-acoes { display: flex; gap: 6px; }
.bs-btn {
  flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 8px; border-radius: 8px;
  font-family: var(--fonte); font-size: 11px; font-weight: 600; text-decoration: none;
}
.bs-btn-ic { width: 12px; height: 12px; }
.bs-btn-sec { border: 1px solid var(--border); background: var(--bg-card); color: var(--text); }
.bs-btn-pri { border: 1px solid transparent; background: var(--accent); color: var(--bg-base); }
.bs-btn-sec:hover { border-color: var(--accent); }
.bs-btn-pri:hover { background: #38bdf8; }
